import sys
import xml.etree.ElementTree as ET
import subprocess
from pathlib import Path

def main():
    if len(sys.argv) != 2:
        print("Usage: python task_runner.py <tasks.xml>", file=sys.stderr)
        sys.exit(1)

    xml_path = Path(sys.argv[1])
    if not xml_path.exists():
        print(f"Error: File '{xml_path}' does not exist.", file=sys.stderr)
        sys.exit(1)

    try:
        tree = ET.parse(xml_path)
        root = tree.getroot()
    except ET.ParseError as e:
        print(f"Error parsing XML file: {e}", file=sys.stderr)
        sys.exit(1)

    token = None
    tasks = []

    for elem in root:
        if elem.tag == 'token':
            token = elem.text.strip()
        elif elem.tag == 'task':
            task_args = elem.text.strip().split()
            processed_args = []
            for arg in task_args:
                if arg == '{token}':
                    processed_args.append(token)
                else:
                    processed_args.append(arg)
            tasks.append(processed_args)

    if token is None:
        print("Error: No <token> element found in XML file.", file=sys.stderr)
        sys.exit(1)

    for task_args in tasks:
        program = task_args[0]
        args = task_args[1:]
        try:
            result = subprocess.run(
                [program] + args,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                text=True,
                check=True
            )
            print(result.stdout, end='')
        except subprocess.CalledProcessError as e:
            print(e.stderr, end='')
        except FileNotFoundError:
            print(f"Error: Command '{program}' not found.", file=sys.stderr)
            sys.exit(1)

    print(f"DONE {len(tasks)}")

if __name__ == "__main__":
    main()
